1	// This file is automatically generated. Do not edit it directly.
2	import { createClient } from '@supabase/supabase-js';
3	import type { Database } from './types';
4	
5	// Enforce environment variables (no hardcoded anon key)
6	const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;
7	const SUPABASE_PUBLISHABLE_KEY = import.meta.env
8	  .VITE_SUPABASE_PUBLISHABLE_KEY as string;
9	
10	if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
11	  throw new Error('[Supabase] Variáveis de ambiente ausentes: VITE_SUPABASE_URL e/ou VITE_SUPABASE_PUBLISHABLE_KEY');
12	}
13	
14	// Import the supabase client like this:
15	// import { supabase } from "@/integrations/supabase/client";
16	
17	/**
18	 * Evento global disparado quando qualquer request REST/RPC volta 401
19	 * (token JWT expirado/inválido). O AuthProvider escuta e decide: tenta
20	 * refresh e, falhando, faz signOut → tela de login. Cobre TODOS os escopos
21	 * (profiles, permissions, mia, lojas, telemetria) sem 401 em cascata preso.
22	 */
23	export const SESSION_UNAUTHORIZED_EVENT = 'supabase:unauthorized';
24	
25	const sessionGuardFetch: typeof fetch = async (input, init) => {
26	  const res = await fetch(input as RequestInfo, init);
27	  if (res.status === 401) {
28	    const url =
29	      typeof input === 'string'
30	        ? input
31	        : input instanceof URL
32	          ? input.href
33	          : (input as Request).url;
34	    // Ignorar 401 do próprio endpoint de auth (login/refresh) pra evitar loop
35	    if (!url.includes('/auth/v1/') && typeof window !== 'undefined') {
36	      try {
37	        window.dispatchEvent(new CustomEvent(SESSION_UNAUTHORIZED_EVENT));
38	      } catch {
39	        /* ambiente sem window — ignora */
40	      }
41	    }
42	  }
43	  return res;
44	};
45	
46	export const supabase = createClient<Database>(
47	  SUPABASE_URL,
48	  SUPABASE_PUBLISHABLE_KEY,
49	  {
50	    auth: {
51	      storage: localStorage,
52	      persistSession: true,
53	      autoRefreshToken: true,
54	    },
55	    // headers globais; o SDK já injeta Authorization quando logado
56	    global: {
57	      fetch: sessionGuardFetch,
58	      headers: {
59	        'x-application': 'momma-stock-insight-frontend',
60	        // Garantir apikey sempre presente nos requests REST
61	        apikey: SUPABASE_PUBLISHABLE_KEY,
62	      },
63	    },
64	    realtime: {
65	      params: {
66	        eventsPerSecond: 10,
67	      },
68	    },
69	  },
70	);
