1	import type { VercelRequest, VercelResponse } from '@vercel/node';
2	
3	const GRAFANA_OTLP_BASE = 'https://otlp-gateway-prod-sa-east-1.grafana.net/otlp';
4	
5	function setCorsHeaders(res: VercelResponse): void {
6	  res.setHeader('Access-Control-Allow-Origin', '*');
7	  res.setHeader('Access-Control-Allow-Headers', 'content-type');
8	  res.setHeader('Access-Control-Allow-Methods', 'POST,OPTIONS');
9	}
10	
11	export default async function handler(
12	  req: VercelRequest,
13	  res: VercelResponse,
14	): Promise<void> {
15	  setCorsHeaders(res);
16	
17	  if (req.method === 'OPTIONS') {
18	    res.status(204).end();
19	    return;
20	  }
21	
22	  if (req.method !== 'POST') {
23	    res.status(405).json({ error: 'Method not allowed' });
24	    return;
25	  }
26	
27	  const token = process.env.GRAFANA_OTLP_TOKEN;
28	  if (!token) {
29	    res.status(500).json({ error: 'GRAFANA_OTLP_TOKEN não configurado' });
30	    return;
31	  }
32	
33	  // Extrair o path após /api/otlp/ — ex: v1/traces, v1/metrics, v1/logs
34	  const pathParam = req.query.path;
35	  const subPath = Array.isArray(pathParam) ? pathParam.join('/') : pathParam;
36	  const targetUrl = `${GRAFANA_OTLP_BASE}/${subPath}`;
37	
38	  try {
39	    const response = await fetch(targetUrl, {
40	      method: 'POST',
41	      headers: {
42	        'Content-Type': req.headers['content-type'] || 'application/json',
43	        Authorization: token,
44	      },
45	      body:
46	        typeof req.body === 'string' || Buffer.isBuffer(req.body)
47	          ? req.body
48	          : JSON.stringify(req.body),
49	    });
50	
51	    const responseBody = await response.text();
52	    res.status(response.status).send(responseBody);
53	  } catch (error) {
54	    console.error('[OTLP Proxy Error]', error);
55	    res.status(502).json({ error: 'Falha ao encaminhar requisição para Grafana Cloud' });
56	  }
57	}
