636	serve(async (req: Request): Promise<Response> => {
637	    if (req.method === 'OPTIONS') {
638	        return new Response('ok', { headers: corsHeaders })
639	    }
640	
641	    if (req.method !== 'POST') {
642	        // GET = retorna self-description simples (útil pra discovery manual)
643	        return new Response(
644	            JSON.stringify({
645	                server: SERVER_NAME,
646	                version: SERVER_VERSION,
647	                protocol: MCP_PROTOCOL_VERSION,
648	                tools_count: TOOLS.length,
649	                endpoint: 'POST JSON-RPC 2.0',
650	                methods: ['initialize', 'tools/list', 'tools/call'],
651	            }, null, 2),
652	            {
653	                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
654	                status: 200,
655	            },
656	        )
657	    }
658	
659	    try {
660	        const authHeader = req.headers.get('authorization')
661	        const body = await req.json()
662	        const rpcResp = await handleRpc(body, authHeader)
663	        return new Response(JSON.stringify(rpcResp), {
664	            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
665	            status: 200,
666	        })
667	    } catch (err) {
668	        return new Response(
669	            JSON.stringify({
670	                jsonrpc: '2.0',
671	                id: null,
672	                error: { code: -32700, message: 'Parse error', data: String(err).slice(0, 200) },
673	            }),
674	            {
675	                headers: { ...corsHeaders, 'Content-Type': 'application/json' },
676	                status: 400,
677	            },
678	        )
679	    }
